const { withAppBuildGradle } = require("expo/config-plugins");

/**
 * Signs release builds with the project's own upload key.
 *
 * Expo's generated `app/build.gradle` points the release build type at
 * `signingConfigs.debug`. A release APK built from it is therefore signed with
 * the generic Android debug key, and Android refuses to install it over a copy
 * signed with the real one: the phone reports only "App not installed", with
 * nothing to say the signature is why.
 *
 * That file is regenerated by every `expo prebuild`, so editing it by hand
 * fixes one build and loses the fix on the next. A plugin is applied each time
 * prebuild runs, which is the only way this stays fixed.
 *
 * The credentials are read from Gradle properties rather than written here, so
 * the keystore's password never enters the repository. Set them in
 * `~/.gradle/gradle.properties`:
 *
 *   REDITOE_DELIVERY_UPLOAD_STORE_FILE=/absolute/path/to/reditoe-upload.jks
 *   REDITOE_DELIVERY_UPLOAD_STORE_PASSWORD=…
 *   REDITOE_DELIVERY_UPLOAD_KEY_ALIAS=…
 *   REDITOE_DELIVERY_UPLOAD_KEY_PASSWORD=…
 *
 * With them absent the release build keeps Expo's debug signing, so a checkout
 * without the key still builds — it just produces an APK that cannot be
 * installed as an update, which is the situation this plugin exists to flag.
 */
const RELEASE_CONFIG = `
        release {
            // Present only when the upload key's details are in Gradle
            // properties; see plugins/with-release-signing.js.
            if (project.hasProperty('REDITOE_DELIVERY_UPLOAD_STORE_FILE')) {
                storeFile file(REDITOE_DELIVERY_UPLOAD_STORE_FILE)
                storePassword REDITOE_DELIVERY_UPLOAD_STORE_PASSWORD
                keyAlias REDITOE_DELIVERY_UPLOAD_KEY_ALIAS
                keyPassword REDITOE_DELIVERY_UPLOAD_KEY_PASSWORD
            }
        }
`;

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (mod) => {
    let contents = mod.modResults.contents;

    if (!contents.includes("REDITOE_DELIVERY_UPLOAD_STORE_FILE")) {
      // Add the release signing config beside the debug one.
      contents = contents.replace(
        /(signingConfigs \{\n)/,
        `$1${RELEASE_CONFIG}`
      );
    }

    /*
     * Point the release build type at it — but only when the key is actually
     * configured, so a build without it still succeeds rather than failing on
     * an empty storeFile.
     *
     * Confined to the `buildTypes` block. Matching on the whole file rewrote
     * the *debug* build type instead: the signing config added just above is
     * also called "release", so a pattern spanning the file found that one
     * first and ran on to the next `signingConfig signingConfigs.debug` it
     * saw, which belongs to debug.
     */
    const marker = "buildTypes {";
    const at = contents.indexOf(marker);
    if (at === -1) {
      throw new Error("with-release-signing: no buildTypes block in build.gradle");
    }
    const head = contents.slice(0, at);
    const tail = contents
      .slice(at)
      .replace(
        /(release \{[^}]*?)signingConfig signingConfigs\.debug/,
        "$1signingConfig project.hasProperty('REDITOE_DELIVERY_UPLOAD_STORE_FILE') ? signingConfigs.release : signingConfigs.debug"
      );
    contents = head + tail;

    mod.modResults.contents = contents;
    return mod;
  });
};
